package com.example.uploads;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class UploadsSecurityTest {
    @TempDir
    Path root;

    @Test
    void benignControl() throws Exception {
        Path dir = Files.createDirectory(root.resolve("uploads"));
        Uploads.save(dir, "photo.txt", "payload");
        assertEquals("payload", new String(Files.readAllBytes(dir.resolve("photo.txt")), StandardCharsets.UTF_8));
    }

    @Test
    void securityKeepsWritesInsideDirectory() throws Exception {
        Path dir = Files.createDirectory(root.resolve("uploads"));
        try {
            Uploads.save(dir, "../escaped.txt", "payload");
        } catch (IllegalArgumentException rejected) {
            // A rejection is the allowed safe outcome; the file system state below decides.
        }
        assertFalse(Files.exists(root.resolve("escaped.txt")));
    }
}
